
//////
//
// Includes
//

// C++ STL
#include <stdexcept>

// FCG Framework
// [includes]
#include <FCG/res.h>
// [includes]

// A real application includes the header generated by fcg_finalize_shaders and uses its FS. This stand-in declaration
// keeps the example compilable without that generated header.
namespace res::shaders {

	extern const cpp_embedlib::EmbeddedFS FS;
}



//////
//
// Function implementations
//

// [resource_usage]
void example ()
{
	auto shader = fcg::res::shader(res::shaders::FS, "simple_shape");
	if (!shader)
		throw std::runtime_error("Shader not embedded");

	auto vertexStage = shader->stage(fcg::ShaderStage::VERTEX);
	if (!vertexStage)
		throw std::runtime_error("The shader has no vertex stage");

	// Pass vertexStage->spirv to Device::createShader.
}
// [resource_usage]

// [builtin_shader]
void builtinExample ()
{
	auto fullscreen = fcg::res::shader("passthrough");
	(void)fullscreen;
}
// [builtin_shader]
